  "pr.pfintro": "মাসের স্যালারি স্লিপ থেকে EPFO unified portal-এর জন্য ECR টেক্সট ফাইল আর চালানের টাকা তৈরি হয়। আগে স্লিপ বানান (Salary ট্যাব); যাদের স্লিপ নেই তাদের নিচে দেখানো হয়েছে।",
  "pr.unver_pf": "আপলোডের আগে দেখে নিন: এটা বানানোর সময় (14 Nov 2026) EPFO-র নিজের ফাইল-স্ট্রাকচার ডকুমেন্ট খোলা যায়নি। 11টি ফিল্ড আর তাদের ক্রম পে-রোল সফটওয়্যার নির্মাতাদের প্রকাশিত তথ্য অনুযায়ী। ফাইলটি EPFO পোর্টালের ECR পেজে আপলোড করুন; পোর্টাল কোনো লাইন বাতিল করলে কারণ জানিয়ে দেয়।",
