  "it.f_mon_h": "বছর শেষে 1 April থেকে রিটার্ন প্রসেস হওয়ার দিন পর্যন্ত। 4 = 31 July-এর মধ্যে ফাইল করা রিটার্ন।",
  "it.m_senior": "60 বা তার বেশি বয়সের বাসিন্দা যাঁর ব্যবসা বা পেশার আয় নেই, তাঁকে অ্যাডভান্স ট্যাক্স দিতে হয় না (section 403(3))। রিটার্ন ফাইল করার সময় বাকি টাকা দিন।",
  "it.m_below": "TDS-এর পরে ট্যাক্স {n}, ₹10,000-এর কম, তাই অ্যাডভান্স ট্যাক্স দিতে হবে না (section 404)। রিটার্ন ফাইল করার সময় বাকি টাকা দিন।",
  "it.m_pres": "প্রিজাম্পটিভ স্কিমে পুরো অ্যাডভান্স ট্যাক্স 15 March-এর মধ্যে দিতে হয় (section 408(2))।",
  "it.m_sur": "আপনার আয় ₹50 লাখের বেশি: সারচার্জ লিখুন, এখানে হিসাব হয় না।",
  "it.m_past": "এই বছর শেষ হয়ে গেছে। 31 March-এর পরে দেওয়া অ্যাডভান্স ট্যাক্স এই বছরের অ্যাডভান্স ট্যাক্স হিসেবে ধরা হয় না; নিচের সুদে দেখায় কম পড়লে কত খরচ।",
  "it.m_season": "আন্দাজে এ পর্যন্ত লাভকে সরলরেখায় পুরো বছরে টেনে নেওয়া হয়। আপনার ব্যবসা মৌসুমি হলে বছরের নিজের হিসাব লিখুন।",
