  "it.basis": "এই হিসাবগুলো যার উপর ভিত্তি করে ({d} অনুযায়ী)",
  "it.b1": "রেট ({d} অনুযায়ী), ট্যাক্স বছর 2026-27: নতুন রেজিমে ₹4 লাখ পর্যন্ত শূন্য, ₹8 লাখ পর্যন্ত 5%, ₹12 লাখ পর্যন্ত 10%, ₹16 লাখ পর্যন্ত 15%, ₹20 লাখ পর্যন্ত 20%, ₹24 লাখ পর্যন্ত 25%, তার বেশি 30%; রিবেট এমন যে ₹12 লাখ পর্যন্ত আয়ে ট্যাক্স লাগে না, ঠিক তার উপরে মার্জিনাল রিলিফ; বেতনে স্ট্যান্ডার্ড ডিডাকশন ₹75,000। পুরনো রেজিম: ₹2.5 লাখ পর্যন্ত শূন্য (60-এ ₹3 লাখ, 80-তে ₹5 লাখ), ₹5 লাখ পর্যন্ত 5%, ₹10 লাখ পর্যন্ত 20%, তার বেশি 30%; ₹5 লাখ পর্যন্ত রিবেট ₹12,500; স্ট্যান্ডার্ড ডিডাকশন ₹50,000। স্যালারি স্লিপ টুল এই রেটই ব্যবহার করে; এই বিল্ডে Finance Act থেকে আবার পড়া হয়নি, তাই দেখে নিন।",
  "it.b2": "অ্যাডভান্স ট্যাক্স (Income-tax Act 2025, sections 403 থেকে 408): TDS-এর পরে ট্যাক্স ₹10,000 বা বেশি হলে দিতে হয়; 15 June-এর মধ্যে 15%, 15 September-এর মধ্যে 45%, 15 December-এর মধ্যে 75%, 15 March-এর মধ্যে সব; প্রিজাম্পটিভ করদাতা সব 15 March-এর মধ্যে দেন; 31 March পর্যন্ত দেওয়া টাকা ওই বছরের জন্য ধরা হয়; 60 বা তার বেশি বয়সের বাসিন্দা যাঁর ব্যবসার আয় নেই, তাঁর ছাড়।",
  "it.b3": "সুদ: section 424 (আগের 234B) হল ট্যাক্সের 90%-এর কম দেওয়া হলে কম পড়া টাকার উপর মাসে বা মাসের অংশে 1%; section 425 (আগের 234C) হল প্রথম তিন কিস্তির প্রতিটির কম পড়া টাকার উপর 3% (15 June-এর মধ্যে 12% আর 15 September-এর মধ্যে 36% দেওয়া হলে নেই) আর March-এর কম পড়া টাকার উপর 1%।",
  "it.b5": "খাতার লাভ মানেই করযোগ্য লাভ নয়: Act অনুযায়ী ডেপ্রিসিয়েশন, বাদ পড়া খরচ আর প্রিজাম্পটিভ নিয়ম তা বদলে দেয়। এই প্ল্যান আর ডেটা শিট আপনার অ্যাকাউন্ট্যান্টকে দিন।",
  "it.b6": "হিসাব করা হয় না: সারচার্জ, বিশেষ রেটে ক্যাপিটাল গেইন, বিদেশি ট্যাক্স রিলিফ, নাবালকের আয়ের ট্যাক্স, আর দেরিতে ফাইলের সুদ।",
  "it.b7": "কিছুই ফাইল হয় না আর আপনার খাতায় কিছু লেখা হয় না।",
  "it.itr_h": "কয়েকটি প্রশ্নের উত্তর দিয়ে দেখুন কোন রিটার্ন ফর্ম মানায়, কেন, আর কোন কাগজ তৈরি রাখবেন।",
