  "it.q_crypto": "আমি crypto-র মতো ভার্চুয়াল ডিজিটাল অ্যাসেট বিক্রি করেছি",
  "it.formd_ITR-1": "বেতন বা পেনশন, দুটো পর্যন্ত বাড়ি সম্পত্তি আর সুদের মতো অন্যান্য উৎসের আয়সহ, আর মোট আয় ₹50 লাখ পর্যন্ত এমন বাসিন্দা ব্যক্তির জন্য।",
  "it.formd_ITR-2": "ব্যবসা বা পেশার আয় নেই এমন ব্যক্তি বা HUF-এর জন্য, যাঁদের ক্যাপিটাল গেইন, ₹50 লাখের বেশি আয়, দুটোর বেশি বাড়ি সম্পত্তি, বিদেশি সম্পদ বা আয় আছে, বা যাঁরা ITR-1-এ পড়েন না।",
  "it.formd_ITR-3": "প্রিজাম্পটিভ স্কিমে নেই এমন ব্যবসা বা পেশার আয়সহ ব্যক্তি বা HUF, ফার্মের পার্টনার, বা যে কেউ ITR-4-এ পড়েন না তাঁদের জন্য।",
  "it.formd_ITR-4": "প্রিজাম্পটিভ ব্যবসার আয়, ₹50 লাখ পর্যন্ত মোট আয়, বেতন বা পেনশন, দুটো পর্যন্ত বাড়ি সম্পত্তি আর অন্যান্য উৎসের আয়সহ বাসিন্দা ব্যক্তি বা HUF-এর জন্য।",
  "it.formd_ITR-5": "ফার্ম, LLP, ব্যক্তিসংঘ (AOP) আর ব্যক্তিসমষ্টি (BOI)-র জন্য।",
  "it.formd_ITR-6": "দাতব্য বা ধর্মীয় উদ্দেশ্যে ছাড় দাবি করে না এমন কোম্পানির জন্য।",
  "it.formd_ITR-7": "ট্রাস্ট, প্রতিষ্ঠান, রাজনৈতিক দল আর এমন ব্যক্তিদের জন্য।",
