  "it.w_pres": "সাধারণ অন্যান্য আয়সহ প্রিজাম্পটিভ ব্যবসার আয় ITR-4-এ মানায়।",
  "it.w_simple": "সীমার মধ্যে শুধু বেতন, বাড়ি সম্পত্তি আর সুদ থাকলে ITR-1-এ মানায়।",
  "it.n_forms": "শর্তগুলো 31 March 2026-এ শেষ হওয়া বছরের জন্য বিজ্ঞাপিত রিটার্ন অনুযায়ী (ট্যাক্স পোর্টালের খবর অনুযায়ী ITR-1 আর ITR-4-এ এখন দুটো পর্যন্ত বাড়ি সম্পত্তি চলে)। ট্যাক্স বছর 2026-27-এর রিটার্ন Income-tax Rules, 2026-এর অধীনে এখনও বিজ্ঞাপিত হয়নি: ফাইল করার আগে ফর্মের নিজের লিস্টে কে ব্যবহার করতে পারবেন না তা পড়ে নিন।",
  "it.n_ltcg": "লিস্টেড শেয়ার বা ইক্যুইটি ফান্ডে ছোট দীর্ঘমেয়াদি লাভ কিছু বছরে ITR-1 আর ITR-4-এ চলত; 2026-27-এর জন্য তা নিশ্চিত নয়, তাই ITR-2 নিরাপদ, আর ফর্মের নিজের লিস্টই চূড়ান্ত।",
  "it.n_ae": "Section 44AE (মাল পরিবহন গাড়ি)-র নিজের শর্ত আছে; প্রিজাম্পটিভ ফর্ম ব্যবহারের আগে দেখে নিন।",
  "it.n_tax": "প্রিজাম্পটিভ রেটের চেয়ে কম লাভ দেখালে খাতা লাগে আর অডিট লাগতে পারে: তখন রিটার্ন ITR-3।",
