  "ca.notlive": "এটা ফাইল হাতে দেওয়া, লাইভ শেয়ার করা লগইন নয়। আপনার অ্যাকাউন্ট্যান্ট খাতা দেখেন ফাইল বানানোর সময় যেমন ছিল তেমন। লাইভ লগইনের জন্য এমন সার্ভার লাগে যা আপনার খাতা রাখে, আর Nivesh Sahayak-এর কোনো সার্ভার নেই: আপনার খাতা আপনার ডিভাইসেই থাকে। নতুন এন্ট্রির জন্য নতুন ফাইল বানান।",
