  "ca.general": "সাধারণ মন্তব্য",
  "cv.h1": "অ্যাকাউন্ট্যান্ট ভিউয়ার: আপনার ক্লায়েন্টের পাঠানো খাতার ফাইল খুলুন",
  "cv.intro": "আপনার ক্লায়েন্ট একটি সময়কালের খাতা একটি ফাইলে ভরে WhatsApp বা ইমেলে আপনাকে পাঠান। এখানে খুলে পড়ুন: বকেয়া, পার্টি, লেজার, ডে বুক, GST হিসাব, ফাইনাল অ্যাকাউন্টস আর প্রতিটি ডকুমেন্ট। খুঁজুন আর ফিল্টার করুন, যেকোনো এন্ট্রিতে প্রশ্ন করুন, আর মন্তব্য একটি ছোট ফাইল হিসেবে ফেরত পাঠান। ফ্রি, লগইন ছাড়া, আর কিছু আপলোড হয় না: ফাইলটি আপনার ব্রাউজারের ভিতরেই পড়া হয়।",
  "cv.drop": ".nsca ফাইলটি এখানে ছাড়ুন",
  "cv.choose": "ফাইল বাছুন",
  "cv.dropnote": "ফাইলটি এই ডিভাইসেই থাকে। এখানে কিছু সেভ হয় না আর এখান থেকে আপনার ক্লায়েন্টের খাতা বদলানো যায় না।",
  "cv.nav.home": "সারাংশ",
  "cv.docs": "ডকুমেন্ট",
  "cv.day": "ডে বুক",
  "cv.fin": "ফাইনাল অ্যাকাউন্টস",
  "cv.gst": "GST হিসাব",
  "cv.cT": "প্রশ্ন আর মন্তব্য",
  "cv.how.h": "এটা কীভাবে কাজ করে",
  "cv.how.1": "আপনার ক্লায়েন্ট Nivesh Sahayak খুলে “আমার ডেটা”, “অ্যাকাউন্ট্যান্টকে পাঠান”-এ যান, আর একটি ব্যবসা আর সময়কালের জন্য “আমার অ্যাকাউন্ট্যান্টের জন্য একটি ফাইল বানান” বাছেন।",
  "cv.how.2": "তিনি আপনাকে ফাইলটি (.nsca দিয়ে শেষ) আর একই মেসেজে একটি ছোট চেক কোড পাঠান।",
  "cv.how.3": "আপনি এই পেজে ফাইলটি খোলেন। পেজ বলে দেয় ফাইলটি অপরিবর্তিত কি না, আর মেলানোর জন্য ক্লায়েন্টের দেওয়া চেক কোড লিখতে দেয়।",
  "cv.how.4": "খাতা পড়ুন, খুঁজুন, আর যেকোনো ডকুমেন্ট, ডে-বুক এন্ট্রি বা স্ক্রিনে “প্রশ্ন বা মন্তব্য যোগ করুন” চাপুন। আপনি যা লেখেন সব এই ব্রাউজারেই থাকে।",
  "cv.how.5": "হয়ে গেলে “প্রশ্ন আর মন্তব্য” খুলে ছোট .nsca-comments ফাইলটি ফেরত পাঠান। আপনার ক্লায়েন্ট সেটা লোড করে প্রতিটি প্রশ্ন এন্ট্রির পাশে দেখেন। তিনি উত্তর দিতে পারেন, আর আপনি সেই উত্তর এখানে লোড করতে পারেন।",
  "cv.live.h": "ফাইল হাতে দেওয়া, লাইভ লগইন নয়",
  "cv.live.p": "এটা ফাইল হাতে দেওয়া। আপনি ক্লায়েন্টের অ্যাকাউন্টে লগইন করেন না আর তিনি পরে যা বদলান তা দেখতে পান না। লাইভ শেয়ার করা লগইনের জন্য এমন সার্ভার লাগে যা খাতা রাখে, আর Nivesh Sahayak-এর কোনো সার্ভার নেই: খাতা আপনার ক্লায়েন্টের ডিভাইসেই থাকে। নতুন সময়কাল বা সংশোধনের পরে ক্লায়েন্টের কাছে নতুন ফাইল চান।",
  "cv.safe.h": "ফাইলে কী আছে, আর কী নেই",
  "cv.safe.p": "আপনার ক্লায়েন্ট টিক দিয়ে ঠিক করেন কী যাবে। সাধারণভাবে ফাইলে থাকে একটি ব্যবসার সময়কালের শেষ পর্যন্ত এন্ট্রি, পার্টি আর আইটেম। কোটেশন আর অর্ডার, বেতন আর স্টাফের রেকর্ড, ফোন নম্বর আর ই-মেল ঠিকানা, আর ব্যবসার ব্যাঙ্ক অ্যাকাউন্টের বিবরণ ক্লায়েন্ট টিক না দিলে বাদ থাকে। ছবি, PIN আর ব্যাকআপ সেটিংস কখনও যায় না। ফাইলে একটি চেকসাম থাকে, তাই কোনো বদল হলে এই পেজে দেখা যায়। কেউ ফাইল এডিট করে আবার চেকসাম হিসাব করলে চেকসাম তা আটকাতে পারে না, তাই ক্লায়েন্টের আলাদা করে পাঠানো চেক কোডের সাথে মিলিয়ে নিন।",
  "cv.readonly": "এটা একটি ফাইলের শুধু-পড়ার ভিউ: এখানে কিছুই বদলানো বা সেভ করা যায় না।",
  "cv.notfile": "এটা Nivesh Sahayak-এর অ্যাকাউন্ট্যান্ট ফাইল (.nsca) নয়।",
  "cv.iscomments": "এটা একটি কমেন্টস ফাইল। আগে খাতার ফাইল (.nsca) খুলুন, তারপর “প্রশ্ন আর মন্তব্য” থেকে কমেন্টস লোড করুন।",
  "cv.newer": "এই ফাইলটি নতুন ভার্সনে বানানো। এই পেজ রিলোড করে আবার চেষ্টা করুন।",
  "cv.nostore": "আপনার মন্তব্য এই ব্রাউজারে রাখা গেল না। এখনই কমেন্টস ফাইল সেভ করুন।",
