  "hm.h.margin.low": "প্রায় কিছুই থাকছে না। দাম বাড়ান, খরচ কমান বা লোকসানের আইটেম বিক্রি বন্ধ করুন।",
  "hm.h.margin.rule": "শেষ 3টি পুরো মাসে বিক্রি থেকে কেনা আর খরচ বাদ, বিক্রির অংশ হিসেবে। 15 বা বেশি হলে স্কোর 100, 0 বা কম হলে 0; আগের 3 মাসের তুলনায় 5 পয়েন্টের বেশি কমলে 20 পয়েন্ট কাটা যায়। হাতের স্টক ধরা হয় না।",
