  "hm.h.creep.low": "খরচ হঠাৎ বেড়েছে। যে খাত বেড়েছে তা খুঁজুন, আর দেখুন সেটা একবারের বিল কি না।",
  "hm.h.creep.rule": "শেষ পুরো মাসের খরচ তার আগের 3 মাসের গড়ের তুলনায়। 5% বা কম বাড়লে স্কোর 100, 40% বা বেশি বাড়লে 0। একবারের বড় বিল এক মাসের জন্য এটা কমিয়ে দেবে।",
  "hm.rm.t": "এই ডিভাইসে রিমাইন্ডার",
  "hm.rm.p": "App খুললে আজ কী করতে হবে তা দেখায়। আপনি চাইলে সবচেয়ে জরুরি লাইনগুলোর জন্য দিনে একবার করে ফোনে নোটিফিকেশনও দেখাতে পারে।",
  "hm.rm.on": "App খুললে একটি নোটিফিকেশন দেখান",
  "hm.rm.nosupport": "এই ব্রাউজার নোটিফিকেশন সমর্থন করে না। “আমার দিন”-এর লিস্ট তবুও কাজ করে।",
  "hm.rm.denied": "এই সাইটের জন্য নোটিফিকেশন বন্ধ করা আছে। ব্রাউজারের সাইট সেটিংসে অনুমতি দিন, তারপর আবার বক্সে টিক দিন।",
  "hm.rm.off": "নোটিফিকেশন বন্ধ।",
  "hm.rm.set": "নোটিফিকেশন চালু। App খুললে সবচেয়ে জরুরি লাইনগুলো দেখা যাবে।",
  "hm.rm.title": "{b}: আজ আপনার নজর চায়",
  "hm.rm.ics": "শেষ তারিখগুলো ফোনের ক্যালেন্ডারে রাখুন",
  "hm.rm.icsp": "পরের 60 দিনের একটি ক্যালেন্ডার ফাইল বানায়: বিলের শেষ তারিখ আর ট্যাক্সের তারিখ। নিজের ক্যালেন্ডারে যোগ করতে ফোনে খুলুন, সেটা এক দিন আগে নিজেই বাজবে, এই App বন্ধ থাকলেও।",
  "hm.rm.icsgo": "ক্যালেন্ডার ফাইল বানান",
  "hm.rm.icsnone": "পরের 60 দিনে ক্যালেন্ডারে রাখার মতো কোনো শেষ তারিখ নেই।",
  "hm.rm.icsdone": "{n}টি তারিখসহ ক্যালেন্ডার ফাইল বানানো হয়েছে। যোগ করতে খুলুন।",
  "hm.rm.recv": "আদায় করুন",
  "hm.rm.pay": "দিন",
  "hm.rm.lim": "ব্রাউজার যা পারে না",
  "hm.rm.l1": "ওয়েব পেজ বন্ধ থাকলে চলতে পারে না, আর এই App-এর পিছনে পুশ মেসেজ পাঠানোর মতো কোনো সার্ভার নেই। তাই App-এর রিমাইন্ডার শুধু App খুললেই দেখা যায়।",
  "hm.rm.l2": "সব হিসাব আপনার ডিভাইসেই হয়, তাই ইন্টারনেট ছাড়াও চলে। আপনার ব্যবসার কোনো তথ্য কোথাও পাঠানো হয় না।",
  "hm.rm.l3": "যে তারিখ কিছুতেই ভোলা চলবে না তার জন্য ক্যালেন্ডার ফাইল ব্যবহার করুন: আপনার ফোনের ক্যালেন্ডার নিজেই বাজবে। এটা আজকের একটা ছবি, তাই নতুন বিল লেখার পরে নতুন ফাইল বানান।",
  "hm.rm.l4": "ইনস্টল করা App-এ, আপনার ফোন অনুমতি দিলে, আইকনের সংখ্যা দেখায় কতগুলো জরুরি কাজ আছে।",
  "hm.tools.t": "কাজ অনুযায়ী সব টুল",
  "hm.tools.p": "Nivesh Sahayak-এর প্রতিটি টুল এক জায়গায়, আপনি কী করতে চান সেই অনুযায়ী সাজানো। সবগুলো ফ্রি আর একই সেভ করা ডেটায় কাজ করে।",
