  "cp.rule_comp_serv": "Service providers with turnover up to ₹50 lakh in the last year can pay tax at 6% in all (3% central and 3% state) under Notification 2/2019-Central Tax (Rate). They issue a bill of supply, cannot collect tax, get no input credit and cannot make inter-State supplies.",
  "cp.rule_einv": "E-invoicing is needed when the aggregate turnover is above ₹5 crore (Notification 13/2020-Central Tax as amended by 10/2023-Central Tax, from 1 August 2023). Exactly ₹5 crore is not above. The notification looks at past years too: ask your CA.",
